def _debug_stage_progress(message: str) -> None:
    if os.environ.get("HIBM_DEBUG_STAGE_PROGRESS") == "1":
        print(f"[hibm-stage {time.perf_counter():.6f}] {message}", flush=True)


def _select_hibm_pressure_projection_solver(
    *,
    requested_pressure_solver: str,
    active_pressure_neumann_rows: int,
) -> tuple[str, bool, str]:
    pressure_solver = str(requested_pressure_solver)
    if (
        int(active_pressure_neumann_rows) > 0
        and pressure_solver in HIBM_PRESSURE_NEUMANN_FV_CG_REQUIRED_SOLVERS
    ):
        return "fv_cg", True, HIBM_PRESSURE_NEUMANN_FV_CG_FORCE_REASON
    return pressure_solver, False, ""


def _combine_projection_reports(
    projection_reports: list[dict[str, Any]],
    *,
    fluid_substeps: int,
    fluid_advection_scheme: str,
) -> dict[str, Any]:
    if not projection_reports:
        return {
            "fluid_substeps": int(fluid_substeps),
            "fluid_advection_scheme": str(fluid_advection_scheme),
        }
    combined = dict(projection_reports[-1])
    combined["fluid_substeps"] = int(fluid_substeps)
    combined["fluid_advection_scheme"] = str(fluid_advection_scheme)
    sum_keys = (
        "cg_project_calls",
        "cg_iterations_total",
        "cg_host_residual_checks",
        "cg_mean_host_reads",
        "cg_mean_projection_count",
        "cg_componentwise_mean_projection_count",
        "cg_breakdown_count",
        "hibm_post_dirichlet_consistency_projection_count",
        "hibm_projection_overflow_singleton_cleanup_cell_count",
        "hibm_projection_overflow_singleton_cleanup_component_count",
        "hibm_projection_tiny_unreached_cleanup_cell_count",
        "hibm_projection_tiny_unreached_cleanup_component_count",
    )
    for key in sum_keys:
        if any(key in report for report in projection_reports):
            combined[key] = sum(
                int(report.get(key, 0)) for report in projection_reports
            )
    max_keys = (
        "cg_iterations_max",
        "cg_initial_relative_residual_max",
        "cg_relative_residual_max",
        "hibm_unreached_component_rhs_mean_max_abs",
        "hibm_unreached_component_rhs_integral_max_abs",
        "pressure_nullspace_component_rhs_mean_max_abs",
        "pressure_nullspace_component_rhs_integral_max_abs",
    )
    for key in max_keys:
        if any(key in report for report in projection_reports):
            combined[key] = max(
                float(report.get(key, 0.0)) for report in projection_reports
            )
    max_int_keys = (
        "hibm_unreached_incompatible_component_count",
        "cg_unreached_component_count",
        "cg_unreached_component_raw_count",
        "cg_unreached_component_largest_cell_count",
        "cg_unreached_component_singleton_count",
        "cg_unreached_component_small_count",
        "cg_unreached_component_small_cell_count",
        "pressure_nullspace_incompatible_component_count",
    )
    for key in max_int_keys:
        if any(key in report for report in projection_reports):
            combined[key] = max(
                int(report.get(key, 0)) for report in projection_reports
            )
    if any(
        "cg_unreached_component_overflow" in report
        for report in projection_reports
    ):
        combined["cg_unreached_component_overflow"] = any(
            bool(report.get("cg_unreached_component_overflow", False))
            for report in projection_reports
        )
    if any("cg_converged_all" in report for report in projection_reports):
        combined["cg_converged_all"] = all(
            bool(report.get("cg_converged_all", True))
            for report in projection_reports
        )
    if any("pressure_solve_failed" in report for report in projection_reports):
        failed = any(
            bool(report.get("pressure_solve_failed", False))
            for report in projection_reports
        )
        combined["pressure_solve_failed"] = failed
        if failed:
            actions = [
                str(report.get("pressure_solve_failure_action", "reported"))
                for report in projection_reports
                if bool(report.get("pressure_solve_failed", False))
            ]
            combined["pressure_solve_failure_action"] = (
                ",".join(dict.fromkeys(actions)) if actions else "reported"
            )
        else:
            combined["pressure_solve_failure_action"] = "none"
    if any(
        "pressure_projection_physical_failure" in report
        for report in projection_reports
    ):
        physical_failed = any(
            bool(report.get("pressure_projection_physical_failure", False))
            for report in projection_reports
        )
        combined["pressure_projection_physical_failure"] = physical_failed
        if physical_failed:
            combined["pressure_projection_physical_failure_reason"] = next(
                str(
                    report.get(
                        "pressure_projection_physical_failure_reason",
                        "",
                    )
                )
                for report in projection_reports
                if bool(report.get("pressure_projection_physical_failure", False))
            )
            combined["pressure_projection_physical_failure_action"] = "reported"
        else:
            combined["pressure_projection_physical_failure_reason"] = ""
            combined["pressure_projection_physical_failure_action"] = "none"
    if any(
        "hibm_post_dirichlet_consistency_projection_applied" in report
        for report in projection_reports
    ):
        combined["hibm_post_dirichlet_consistency_projection_applied"] = any(
            bool(
                report.get(
                    "hibm_post_dirichlet_consistency_projection_applied",
                    False,
                )
            )
            for report in projection_reports
        )
    breakdown = ""
    for report in projection_reports:
        if report.get("cg_breakdown"):
            breakdown = str(report["cg_breakdown"])
    if breakdown:
        combined["cg_breakdown"] = breakdown
    return combined


def _vector3(value: Sequence[float], *, name: str) -> tuple[float, float, float]:
    try:
        vector = tuple(float(component) for component in value)
    except TypeError as exc:
        raise ValueError(f"{name} must contain exactly 3 components") from exc
    if len(vector) != 3:
        raise ValueError(f"{name} must contain exactly 3 components")
    if any(not math.isfinite(component) for component in vector):
        raise ValueError(f"{name} must contain only finite values")
    return (vector[0], vector[1], vector[2])


_F32_MAX = float(np.finfo(np.float32).max)


def _f32_round_trip(value: float, *, name: str) -> float:
    scalar = float(value)
    with np.errstate(over="ignore", under="ignore", invalid="ignore"):
        converted = float(np.float32(scalar))
    if (
        not math.isfinite(scalar)
        or not math.isfinite(converted)
        or (scalar != 0.0 and converted == 0.0)
    ):
        raise ValueError(
            f"{name} must remain finite without non-zero underflow when converted to f32"
        )
    return converted


def _vector3_for_f32_field(
    value: Sequence[float],
    *,
    name: str,
) -> tuple[float, float, float]:
    vector = _vector3(value, name=name)
    return tuple(_f32_round_trip(component, name=name) for component in vector)


def _scalar_for_f32_field(value: float, *, name: str) -> float:
    return _f32_round_trip(value, name=name)


def _normalize_vector3(value: Sequence[float], *, name: str) -> tuple[float, float, float]:
    vector = _vector3(value, name=name)
    norm = math.hypot(*vector)
    if norm <= 0.0:
        raise ValueError(f"{name} must contain non-zero vectors")
    return tuple(component / norm for component in vector)


def _cell_vector3(value: Sequence[int], *, name: str) -> tuple[int, int, int]:
    try:
        vector = tuple(int(component) for component in value)
    except TypeError as exc:
        raise ValueError(f"{name} must contain exactly 3 components") from exc
    if len(vector) != 3:
        raise ValueError(f"{name} must contain exactly 3 components")
    if any(component < 0 for component in vector):
        raise ValueError(f"{name} must contain non-negative cell indices")
    return (vector[0], vector[1], vector[2])


def _strict_nonnegative_int(value: Any, *, name: str) -> int:
    if isinstance(value, (bool, np.bool_)) or not isinstance(
        value,
        (int, np.integer),
    ):
        raise TypeError(f"{name} must be a non-bool integer")
    result = int(value)
    if result < 0:
        raise ValueError(f"{name} must be nonnegative")
    return result


def _require_counted_field_capacity(
    field,
    count: int,
    *,
    count_name: str,
    field_name: str,
) -> None:
    requested = _strict_nonnegative_int(count, name=count_name)
    shape = getattr(field, "shape", None)
    if shape is None or len(shape) < 1:
        raise TypeError(f"{field_name} must expose a leading capacity")
    capacity = int(shape[0])
    if requested > capacity:
        raise ValueError(
            f"{count_name}={requested} exceeds {field_name} capacity={capacity}"
        )


def _require_i32_counted_field(
    field,
    count: int,
    *,
    count_name: str,
    field_name: str,
    trailing_shape: tuple[int, ...],
) -> None:
    """Validate an integer device field without copying it to the host."""

    _require_counted_field_capacity(
        field,
        count,
        count_name=count_name,
        field_name=field_name,
    )
    if getattr(field, "dtype", None) != ti.i32:
        raise TypeError(f"{field_name} must use signed int32 storage")
    components = getattr(field, "n", None)
    if trailing_shape == () and components is not None:
        raise TypeError(f"{field_name} must be a scalar field")
    if trailing_shape and (
        components != trailing_shape[0] or getattr(field, "m", 1) != 1
    ):
        raise TypeError(f"{field_name} must be a {trailing_shape[0]}-vector field")


def _component_divergence_stencil_touch_mask(
    component_mask: np.ndarray,
) -> np.ndarray:
    touch = np.any(component_mask, axis=-1)
    touch[:-1, :, :] |= component_mask[1:, :, :, 0]
    touch[:, :-1, :] |= component_mask[:, 1:, :, 1]
    touch[:, :, :-1] |= component_mask[:, :, 1:, 2]
    return touch


def _pressure_disconnected_component_distribution_kwargs(
    fluid: Any,
) -> dict[str, int]:
    return {
        "component_raw_count": int(
            getattr(fluid, "last_hibm_pressure_unreached_component_raw_count", 0)
        ),
        "largest_component_cell_count": int(
            getattr(
                fluid,
                "last_hibm_pressure_unreached_component_largest_cell_count",
                0,
            )
        ),
        "singleton_component_count": int(
            getattr(
                fluid,
                "last_hibm_pressure_unreached_component_singleton_count",
                0,
            )
        ),
        "small_component_threshold_cells": int(
            getattr(
                fluid,
                "last_hibm_pressure_unreached_component_small_threshold_cells",
                HIBM_PRESSURE_DISCONNECTED_SMALL_COMPONENT_THRESHOLD_CELLS,
            )
        ),
        "small_component_count": int(
            getattr(
                fluid,
                "last_hibm_pressure_unreached_component_small_count",
                0,
            )
        ),
        "small_component_cell_count": int(
            getattr(
                fluid,
                "last_hibm_pressure_unreached_component_small_cell_count",
                0,
            )
        ),
    }


def hibm_mpm_pressure_disconnected_region_report(
    fluid: Any,
    *,
    primary_region_id: int | None,
    secondary_region_id: int | None,
    include_field_diagnostics: bool = False,
) -> HibmMpmPressureDisconnectedRegionReport:
    # Gate on the raw unreached-cell count (obstacle==0 & barrier==0 &
    # reachable==0), NOT last_hibm_pressure_unreached_cell_count: that
    # narrower counter excludes cells that are active velocity-Dirichlet
    # rows owned by a known region (see
    # CartesianFluidSolver._velocity_dirichlet_pressure_barrier /
    # _count_hibm_pressure_outlet_unreached_cells_kernel), so it can read 0
    # while this report's own `unreached` mask below (and the
    # pressure-interface row-stencil cells it is responsible for locating)
    # is still non-empty. The raw count is computed device-side in the same
    # kernel pass, so this stays a zero-host-round-trip early-exit.
    known_raw_cell_count = int(
        getattr(fluid, "last_hibm_pressure_unreached_raw_cell_count", -1)
    )
    if not bool(include_field_diagnostics):
        # The production coupling path calls this report twice per FSI step.
        # Keep that path Taichi-resident: all values below were already reduced
        # device-side by the reachability/component kernels. Bounding boxes and
        # row-region stencil attribution require five full-grid downloads and
        # are therefore available only through the explicit diagnostic mode.
        return HibmMpmPressureDisconnectedRegionReport(
            cell_count=max(known_raw_cell_count, 0),
            component_count=int(
                getattr(fluid, "last_hibm_pressure_unreached_component_count", 0)
            ),
            **_pressure_disconnected_component_distribution_kwargs(fluid),
            component_overflow=bool(
                getattr(fluid, "last_hibm_pressure_unreached_component_overflow", False)
            ),
            component_labels_converged=bool(
                getattr(fluid, "last_hibm_pressure_component_labels_converged", True)
            ),
        )
    if known_raw_cell_count == 0:
        return HibmMpmPressureDisconnectedRegionReport(
            component_count=int(
                getattr(fluid, "last_hibm_pressure_unreached_component_count", 0)
            ),
            **_pressure_disconnected_component_distribution_kwargs(fluid),
            component_overflow=bool(
                getattr(fluid, "last_hibm_pressure_unreached_component_overflow", False)
            ),
            component_labels_converged=bool(
                getattr(fluid, "last_hibm_pressure_component_labels_converged", True)
            ),
        )
    obstacle = fluid.obstacle.to_numpy()
    reachable = fluid.hibm_pressure_outlet_reachable.to_numpy()
    barrier = fluid.hibm_pressure_reachability_barrier.to_numpy()
    unreached = (obstacle == 0) & (barrier == 0) & (reachable == 0)
    cell_count = int(np.count_nonzero(unreached))
    if cell_count <= 0:
        return HibmMpmPressureDisconnectedRegionReport(
            component_count=int(
                getattr(fluid, "last_hibm_pressure_unreached_component_count", 0)
            ),
            **_pressure_disconnected_component_distribution_kwargs(fluid),
            component_overflow=bool(
                getattr(fluid, "last_hibm_pressure_unreached_component_overflow", False)
            ),
            component_labels_converged=bool(
                getattr(fluid, "last_hibm_pressure_component_labels_converged", True)
            ),
        )

    coords = np.argwhere(unreached)
    mins = coords.min(axis=0)
    maxs = coords.max(axis=0)
    active_mask = fluid.velocity_dirichlet_boundary_active_component_mask.to_numpy()
    component_region = fluid.velocity_dirichlet_boundary_component_region_id.to_numpy()
    active_components = np.stack(
        tuple((active_mask & bit) != 0 for bit in (1, 2, 4)),
        axis=-1,
    )
    primary_mask = np.zeros_like(active_components, dtype=bool)
    if primary_region_id is not None and int(primary_region_id) >= 0:
        primary_mask = active_components & (
            component_region == int(primary_region_id)
        )
    secondary_mask = np.zeros_like(active_components, dtype=bool)
    if secondary_region_id is not None and int(secondary_region_id) >= 0:
        secondary_mask = (
            active_components
            & (component_region == int(secondary_region_id))
            & ~primary_mask
        )
    unassigned_mask = active_components & (component_region < 0)
    other_mask = active_components & ~(
        primary_mask | secondary_mask | unassigned_mask
    )

    primary_touch = _component_divergence_stencil_touch_mask(primary_mask)
    secondary_touch = _component_divergence_stencil_touch_mask(secondary_mask)
    other_touch = _component_divergence_stencil_touch_mask(other_mask)
    unassigned_touch = _component_divergence_stencil_touch_mask(unassigned_mask)
    return HibmMpmPressureDisconnectedRegionReport(
        cell_count=cell_count,
        component_count=int(
            getattr(fluid, "last_hibm_pressure_unreached_component_count", 0)
        ),
        **_pressure_disconnected_component_distribution_kwargs(fluid),
        component_overflow=bool(
            getattr(fluid, "last_hibm_pressure_unreached_component_overflow", False)
        ),
        component_labels_converged=bool(
            getattr(fluid, "last_hibm_pressure_component_labels_converged", True)
        ),
        min_i=int(mins[0]),
        min_j=int(mins[1]),
        min_k=int(mins[2]),
        max_i=int(maxs[0]),
        max_j=int(maxs[1]),
        max_k=int(maxs[2]),
        primary_region_stencil_cell_count=int(
            np.count_nonzero(unreached & primary_touch)
        ),
        secondary_region_stencil_cell_count=int(
            np.count_nonzero(unreached & secondary_touch)
        ),
        other_region_stencil_cell_count=int(np.count_nonzero(unreached & other_touch)),
        unassigned_region_stencil_cell_count=int(
            np.count_nonzero(unreached & unassigned_touch)
        ),
    )


@ti.data_oriented
class HibmMpmSurfaceMarkers:
    def __init__(
        self,
        marker_capacity: int,
        projection_triangle_capacity: int | None = None,
        runtime: TaichiRuntimeConfig | None = None,
    ) -> None:
        init_taichi(runtime)
        if int(marker_capacity) <= 0:
            raise ValueError("marker_capacity must be positive")
        self.marker_capacity = int(marker_capacity)
        if projection_triangle_capacity is None:
            projection_triangle_capacity = self.marker_capacity
        if int(projection_triangle_capacity) <= 0:
            raise ValueError("projection_triangle_capacity must be positive")
        self.projection_triangle_capacity = int(projection_triangle_capacity)
        self.marker_count = 0
        # ``marker_count`` is the physical traction/scatter population.
        # Projection-only boundary vertices may extend the search/BC surface
        # without entering stress, force, MPM-feedback, or pressure-pair
        # accounting.  With no derived vertices both counts are identical.
        self.projection_vertex_count = 0
        self.projection_triangle_count = 0
        # Segments and triangles share the same fixed three-index device
        # storage.  A segment is encoded as ``(ia, ib, -1)``; only one
        # primitive family is active at a time, so adding line-surface
        # provenance does not allocate another large Taichi field.
        self.projection_segment_count = 0
        # Host-owned generation for every attempted marker-geometry write.
        # Cache consumers use this independently from marker_count so moving a
        # fixed-size surface can never reuse topology classified for an older
        # position/normal state.
        self.marker_geometry_revision = 0
        self.pressure_pair_anchor_geometry_revision: int | None = None
        self.pressure_pair_anchor_marker_geometry_sha256 = ""
        self._open_ribbon_tip_cap_binding: tuple[object, ...] | None = None
